{
  "gate_token": "yPeRuJOBEcrVQ8IATCrIHw",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds her map at the ruined city's edge.",
      "visual_description": "A windswept ridge overlooks a broken skyline of toppled spires and tattered royal banners; ink-stained coat flaps as a brass compass spins wildly.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false invitations ahead.",
      "visual_description": "A small oil lamp held aloft at dusk, its single flame-eye narrowed, casting a long warning shadow across cracked cobblestones.",
      "characters": ["mara_the_cartographguer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the gaping castle gates.",
      "visual_description": "A clockwork fox with blue glass eyes crouches before enormous iron-banded gates hanging askew, key-wind tail ticking softly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver arrives through a shattered cathedral window.",
      "visual_description": "A figure in a clear diving helmet steps out of a stained-glass pane as if from water, coat surface rippling with reflected city fires.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team assembles in a collapsed market square.",
      "visual_description": "Four companions gather among overturned stalls and faded royal banners; lamp glow lights inked maps spread on a broken fountain rim.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower looms, whispering false promises.",
      "visual_description": "A leaning black tower wreathed in violet smoke, its windows flickering with phantom faces; the lamp's eye burns brighter in alarm.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a great winged beast echo through alleys.",
      "visual_description": "Claw-scored walls and scorched cobbles in a narrow lane; Tin Fox sniffs a charred banner while distant roars rattle loose shutters.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "They discover the sleeping tax collector slumped in a kiosk.",
      "visual_description": "A plump official snores against a ledger pillow, stamped papers stuck to his sleeves, oblivious to the smoking ruins behind him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara questions him; he yawns and stamps her sleeve.",
      "visual_description": "The official, half-asleep, presses a red seal on Mara's wrist while she frowns; the lamp rolls its flame-eye in disgust.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Frightened faces peer from boarded windows.",
      "visual_description": "Eyes glint behind cracked shutters along a narrow lane; Glass Diver presses a gloved hand to a windowpane, promising return.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "An armored patrol clatters past on the avenue above.",
      "visual_description": "From a basement grate, the team watches plated boots and pike-shafts march by under torn royal banners; Tin Fox freezes mid-step.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door blocks the keep's lower hall.",
      "visual_description": "A tall door inlaid with shifting silver runes pulses like a heartbeat; the oracle lamp hovers close, reading the glyphs aloud.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Glass Diver slips through the door's mirrored panel.",
      "visual_description": "The diver dissolves into the door's reflective surface, coat shimmering; ripples spread across the runes as Tin Fox watches anxiously.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Inside, the captive waits in a glass-walled cell.",
      "visual_description": "A small dim chamber where a chained figure sits behind warped glass; Glass Diver's reflection multiplies around them as locks click open.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The lamp warns of a collapsing ceiling above.",
      "visual_description": "Dust rains through cracks; the oracle lamp blazes red while Mara braces a beam, her compass spinning toward a hidden exit.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Tin Fox leads them through smoke-filled corridors.",
      "visual_description": "The clockwork fox sprints ahead, blue eyes cutting through gray haze; banners burn overhead as the team races behind.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They reach the long bridge over the chasm river.",
      "visual_description": "A narrow stone bridge stretches across a misty gorge; behind them, the cursed tower finally collapses in a column of violet sparks.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "On the far bank, they look back at the ruined city.",
      "visual_description": "Four silhouettes on a green hill at dawn; the lamp's eye dims to a gentle blue, and Mara rolls up her map with a small, weary smile.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

